n-items:center;font-size:10px;color:rgba(255,255,255,.69)}.star{color:#f3a267;margin-right:5px}.mini-divider{height:1px;background:rgba(255,255,255,.16);margin:12px 0 9px}.time-row{font:9px 'DM Mono',monospace;letter-spacing:.07em;color:rgba(255,255,255,.58)}.time-row .mono{font-size:11px;color:#fff}.notice{top:44%;left:50%;transform:translate(-50%,-50%) translateY(10px);padding:11px 17px;border-radius:9px;border:1px solid rgba(255,255,255,.25);background:rgba(18,33,42,.83);backdrop-filter:blur(12px);display:flex;gap:9px;align-items:center;font-size:12px;opacity:0;transition:.24s;pointer-events:none}.notice.show{opacity:1;transform:translate(-50%,-50%)}.notice-icon{color:#f3a267}.center-overlay{inset:0;display:grid;place-items:center;background:rgba(9,19,26,.14);backdrop-filter:blur(2px);transition:opacity .3s,visibility .3s}.center-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-content{background:linear-gradient(145deg,rgba(18,32,41,.93),rgba(12,24,32,.92));border:1px solid rgba(255,255,255,.19);box-shadow:0 25px 100px rgba(3,13,19,.3);backdrop-filter:blur(20px);border-radius:15px}.intro-card{width:min(440px,calc(100vw - 36px));padding:30px 35px 25px}.location-tag{display:flex;align-items:center;gap:8px;font:500 9px 'DM Mono',monospace;letter-spacing:.14em;color:rgba(255,255,255,.65)}h1{font:700 clamp(42px,6.6vw,63px)/.91 'Space Grotesk',sans-serif;letter-spacing:-.07em;margin:19px 0 15px}h1 span{color:#f0a269}.intro-copy{font-size:12px;line-height:1.7;color:rgba(255,255,255,.68);max-width:330px;margin:0 0 19px}.route-preview{display:flex;align-items:center;gap:11px;padding:12px 13px;border:1px solid rgba(255,255,255,.14);border-radius:9px;background:rgba(255,255,255,.045);margin-bottom:14px}.preview-icon{font-size:22px}.route-preview strong{display:block;font-size:12px}.route-preview strong span{color:var(--orange);padding:0 3px}.route-preview small{display:block;font:9px 'DM Mono',monospace;letter-spacing:.08em;color:rgba(255,255,255,.53)