-style:normal;color:#f2a267;padding-left:9px}.mobile-controls{display:none;left:0;right:0;bottom:72px;justify-content:space-between;align-items:flex-end;padding:0 22px;pointer-events:none}.touch-control{pointer-events:auto;color:#fff;border:1px solid rgba(255,255,255,.42);background:rgba(16,28,36,.48);backdrop-filter:blur(8px);touch-action:none;user-select:none;-webkit-user-select:none}.steering{width:62px;height:62px;border-radius:50%;font:36px 'DM Sans',sans-serif}.touch-pedals{display:flex;gap:9px}.brake,.accelerate{height:52px;min-width:65px;border-radius:13px;display:flex;flex-direction:column;align-items:center;justify-content:center}.accelerate{background:rgba(229,143,80,.72);border-color:rgba(255,212,168,.69)}.touch-control span{font-size:17px;font-weight:600;line-height:1}.touch-control small{font:7px 'DM Mono',monospace;letter-spacing:.05em;margin-top:4px}.touch-control:active{transform:scale(.94);background:rgba(242,156,86,.76)}
