const tabs = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = tabs.find(tab => tab.type === 'page');
if (!page) throw new Error('No Chromium page found');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
};
function call(method, params = {}) {
  return new Promise((resolve, reject) => {
    const callId = ++id;
    pending.set(callId, { resolve, reject });
    ws.send(JSON.stringify({ id: callId, method, params }));
  });
}
const evaluate = async expression => (await call('Runtime.evaluate', { expression, returnByValue: true })).result.value;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
await call('Runtime.enable');
const errors = [];
ws.addEventListener('message', event => { const m = JSON.parse(event.data); if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text); });
await evaluate("document.getElementById('start-button').click()");
await evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}))");
await sleep(1800);
const accelerating = await evaluate("({speed:document.getElementById('speed').textContent,distance:document.getElementById('distance-label').textContent,status:document.getElementById('status-pill').textContent})");
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:'ArrowUp',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowLeft',bubbles:true}))");
await sleep(600);
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:'ArrowLeft',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keydown',{key:' ',bubbles:true}))");
await sleep(800);
const braking = await evaluate("({speed:document.getElementById('speed').textContent,distance:document.getElementById('distance-label').textContent})");
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:' ',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keydown',{key:'p',bubbles:true}))");
const paused = await evaluate("!document.getElementById('pause-overlay').classList.contains('hidden')");
await evaluate("document.getElementById('resume-button').click()");
const resumed = await evaluate("document.getElementById('pause-overlay').classList.contains('hidden')");
await evaluate("document.getElementById('restart-button').click()");
const restarted = await evaluate("({speed:document.getElementById('speed').textContent,distance:document.getElementById('distance-label').textContent,status:document.getElementById('status-pill').textContent})");
console.log(JSON.stringify({accelerating,braking,paused,resumed,restarted,errors}, null, 2));
ws.close();

