const tabs = await (await fetch('http://127.0.0.1:9222/json')).json();
const page = tabs.find(tab => tab.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => { const m = JSON.parse(event.data); if (m.id && pending.has(m.id)) { const p = pending.get(m.id); pending.delete(m.id); m.error ? p.reject(new Error(m.error.message)) : p.resolve(m.result); } };
const call = (method, params = {}) => new Promise((resolve, reject) => { const n = ++id; pending.set(n,{resolve,reject}); ws.send(JSON.stringify({id:n,method,params})); });
const evaluate = async expression => (await call('Runtime.evaluate',{expression,returnByValue:true})).result.value;
const sleep = ms => new Promise(resolve => setTimeout(resolve,ms));
await call('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true});
await evaluate("document.getElementById('start-button').click();window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}))");
let target = null;
for(let i=0;i<200;i++){const km=await evaluate("parseFloat(document.getElementById('distance-label').textContent)");if(km>=31){target=km;break;}await sleep(100);}
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:'ArrowUp',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keydown',{key:' ',bubbles:true}))");
for(let i=0;i<100;i++){const speed=await evaluate("document.getElementById('speed').textContent");if(Number(speed)===0)break;await sleep(100);}
await sleep(400);
const stopResult = await evaluate("({distance:document.getElementById('distance-label').textContent,passengers:document.getElementById('passengers').textContent,notice:document.getElementById('notice-text').textContent})");
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:' ',bubbles:true}));window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}))");
const touchVisible = await evaluate("getComputedStyle(document.getElementById('mobile-controls')).display !== 'none'");
await evaluate("const b=document.querySelector('[data-control=accelerate]');b.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:1}));");
await sleep(500);
const touchSpeed = await evaluate("document.getElementById('speed').textContent");
await evaluate("const b=document.querySelector('[data-control=accelerate]');b.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:1}));window.dispatchEvent(new KeyboardEvent('keyup',{key:'ArrowUp',bubbles:true}))");
await evaluate("window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}))");
for(let i=0;i<500;i++){const finished=await evaluate("!document.getElementById('finish-overlay').classList.contains('hidden')");if(finished)break;await sleep(100);}
const completion = await evaluate("({visible:!document.getElementById('finish-overlay').classList.contains('hidden'),status:document.getElementById('status-pill').textContent,score:document.getElementById('final-score').textContent,passengers:document.getElementById('final-passengers').textContent})");
await evaluate("window.dispatchEvent(new KeyboardEvent('keyup',{key:'ArrowUp',bubbles:true}));document.getElementById('restart-button').click()");
const replay = await evaluate("({finishHidden:document.getElementById('finish-overlay').classList.contains('hidden'),distance:document.getElementById('distance-label').textContent,passengers:document.getElementById('passengers').textContent})");
console.log(JSON.stringify({approachKm:target,stopResult,touchVisible,touchSpeed,completion,replay},null,2));
ws.close();

