input.command:
node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.connectOverCDP('http://127.0.0.1:9222');
const pages = browser.contexts().flatMap(c => c.pages());
for (const page of pages) {
  console.log('url', page.url());
  await page.reload({waitUntil:'load'});
  await page.evaluate(() => document.fonts.ready);
  const result = await page.evaluate(() => {
    const chip = document.querySelector('#pause-chip');
    const clock = document.querySelector('#clock');
    const rect = el => { const r=el.getBoundingClientRect(); return {x:r.x,y:r.y,width:r.width,height:r.height,bottom:r.bottom,right:r.right}; };
    return {viewport:{width:innerWidth,height:innerHeight},chip:rect(chip),clock:rect(clock),score:rect(document.querySelector('.score-card')),overlay:getComputedStyle(document.querySelector('#pause-chip')).top};
  });
  console.log(JSON.stringify(result));
  await page.screenshot({path:'/tmp/opencode/pause-chip-verified.png'});
  break;
}
await browser.close();
EOF
